insert into public.jev_questions (question_set, id, body, position) values
  ('entry', 'bundles_requests', $json${"criteria":{"false":{"also":"Necessary supporting work — the test for the feature, the migration the change needs — belongs to the same request.","when":"Everything asked for serves one outcome, however many files or steps that takes."},"true":{"examples":["a refactor plus an unrelated new feature plus a dependency upgrade","\"and while you are at it, also...\"","a list of unrelated defects"],"when":"Two or more independent goals are asked for at once, each of which could be delivered, reviewed and verified on its own."}},"instructions":{"guidance":"Judge whether the parts share one outcome. Several files, several steps or a long description of one coherent job is a single request. Separate goals that merely arrived in the same message are a bundle.","question":"Does `user_request` bundle work that would be better asked for separately?"},"type":"noul"}$json$::jsonb, 0),
  ('entry', 'goal_is_clear', $json${"criteria":{"false":{"examples":["\"fix this\", \"improve it here\", \"make it faster\" with nothing to anchor them","names a topic without saying what should change about it","several possible goals with no sign of which one is meant"],"when":"The outcome has to be guessed."},"true":{"examples":["asks for a named capability, file or fix","states the problem to be gone and what working looks like","asks a question whose answer would settle a decision"],"when":"The outcome is stated: the request names the behaviour, artefact or answer it expects to exist afterwards."}},"instructions":{"guidance":"Look for the intended outcome, not for politeness or detail. A request can be short and still name its outcome exactly.","question":"Does `user_request` state what the developer wants to be true once the work is finished?"},"type":"noul"}$json$::jsonb, 1),
  ('entry', 'says_when_done', $json${"criteria":{"false":{"examples":["only an adjective as the target: \"better\", \"cleaner\", \"faster\", with no measure","asks for a change with no stated effect to look for"],"when":"There is no way to tell the work apart from unfinished work."},"true":{"examples":["names a test, a command or an output that must appear","gives an input and the expected result","describes the finished behaviour precisely enough to verify"],"when":"A check is stated or clearly implied by a precise end state."}},"instructions":{"guidance":"Look for something checkable: a test that should pass, a command whose output is stated, an input and its expected output, an acceptance condition, or a described end state precise enough to compare against.","question":"Does `user_request` say how the developer will confirm the work is done?"},"type":"noul"}$json$::jsonb, 2),
  ('entry', 'says_where', $json${"criteria":{"false":{"examples":["a change described only by its effect, in a project with many plausible homes for it","\"in the system\", \"in the code\", \"somewhere in the backend\""],"not_a_defect":["a general question that does not touch this project at all"],"when":"No place is given and the request is not self-locating."},"true":{"when":"The request points at a place: a path or filename, a named symbol, a module, a screen, a route, or a layer of the system."}},"instructions":{"guidance":"A location can be a path, a file, a module, a function, a screen, a layer or a named subsystem. Judge whether someone who knows this project could open the right place without guessing.","question":"Does `user_request` say where in the project the work belongs?"},"type":"noul"}$json$::jsonb, 3),
  ('entry', 'scope', $json${"criteria":[{"examples":["Fix the typo in this log message","Rename `check` to `validate` everywhere","Increase the timeout to 60 seconds"],"what":"A small correction inside code that already exists and already works: a rename, a typo, a changed default, one added guard, one adjusted style rule, or a question answered in a line."},{"examples":["Add a --json flag to the CLI","Create the paginated table component","Find and fix why the cache returns stale results"],"what":"One capability delivered end to end: a new screen, endpoint, command, adapter or test suite, or a defect whose repair touches a handful of files that already exist."},{"examples":["Migrate persistence from JSON files to SQLite","Build the multi-agent orchestration layer","Rewrite the app so every provider streams"],"what":"A whole system or a change that reaches across the codebase: a new subsystem, a migration, a redesign of how existing parts interact, or work whose extent cannot be stated without exploring the repository first."}],"instructions":{"background":"`project` names the repository and the languages it is written in.","focus":"Judge the size of the work the request describes, not how long or polite the sentence is. One terse line can ask for a whole system, and a long paragraph can ask for a rename.","question":"How much of this codebase does `user_request` ask to be changed or produced?"},"type":"score"}$json$::jsonb, 4),
  ('routing', 'complexity', $json${"criteria":[{"examples":["How do I list branches in git?","Fix this typo in the log message","Hi, how are you?"],"what":"Answerable straight away from general knowledge or a single obvious line: a factual question, a command or syntax lookup, a rename, a typo, a greeting. Nothing has to be read first to be confident the answer is right."},{"examples":["Add a null check to this parser function","Explain what this single function does","Write a unit test for this pure helper"],"what":"A self-contained change or explanation confined to one file or one function, where the right approach is obvious as soon as that code is in view. No design decision and no coordination between separate parts of the system."},{"examples":["Add a new provider adapter alongside the existing ones","Find why the cache returns stale results after a config reload","Thread a new option through the CLI, config and router"],"what":"Several related files must be read and held together to get it right: a feature that touches a handful of call sites, a defect whose cause is somewhere other than where the symptom appears, or a change that must keep an existing interface or callers working."},{"examples":["Migrate the whole persistence layer from JSON files to SQLite","Redesign how sessions and memory interact so multiple windows stay consistent","Make the orchestrator resilient to a provider failing mid-stream"],"what":"A design decision with consequences across the codebase is required first: a cross-cutting refactor or migration, work spanning several subsystems or layers, requirements ambiguous enough that they must be settled before coding, reasoning about concurrency, data integrity or security, or a change whose blast radius cannot be established without exploring the repository."}],"instructions":{"background":"`project` describes the repository and its languages and `candidate_files` lists files a keyword search matched. Use them to gauge how much of the system the work reaches into.","focus":"Judge the difficulty of the underlying task, not the length, politeness or wording of the request. A single terse sentence can describe a repository-wide migration, and a long message can describe a one-line change.","question":"How much work and how much of this codebase must an experienced software engineer take in to carry out `user_request` correctly and completely?"},"type":"score"}$json$::jsonb, 0),
  ('routing', 'intent', $json${"criteria":{"analysis":{"examples":["Explain how model routing works here","Why does this endpoint return 401 only in production?","Trace where this value is set before it reaches the database"],"not_for":"Judging whether the code is good, which is `review`; or changing the code, which is `code` or `refactor`.","what":"Understand or explain something that already exists: how a piece of code works, why a behaviour or a failure happens, what a dependency does, or how the project is laid out."},"code":{"examples":["Implement an HTTP client for the payments API","Fix the panic that happens when the config file is missing","Add a --json flag to the CLI"],"not_for":"Restructuring code that already behaves correctly, which is `refactor`; writing tests, which is `test`; user-interface work, which is `frontend`.","what":"Produce working code that does not exist yet, or repair code that is behaving incorrectly: a new feature, a new function, endpoint or script, a bug fix, or an integration with an external system."},"frontend":{"examples":["Create a paginated table component in React","The sidebar collapses incorrectly on mobile","Adjust the theme tokens so dark mode passes contrast checks"],"not_for":"Server-side or library code that merely happens to feed a UI, which is `code`.","what":"Work whose subject is the user interface: components, markup, styling, layout, client-side state, accessibility, or browser behaviour, in React, Vue, HTML, CSS or an equivalent."},"general":{"examples":["Hi, how are you?","What should I work on next?","Can you help me with something?"],"not_for":"Requests that clearly belong to another option even when phrased casually or briefly.","what":"Anything none of the other options describe: greetings and small talk, questions about the assistant itself, process or planning questions, open-ended advice, or a request too vague to place. This is the deliberate no-match outcome."},"refactor":{"examples":["Extract this duplicated logic into a helper","Split this 800-line file into modules","Make this loop allocate less memory"],"not_for":"Fixing behaviour that is wrong, which is `code`; or pointing out problems without changing anything, which is `review`.","what":"Change the internal structure of code that already works, without changing what it does: renaming, extracting, de-duplicating, simplifying, reorganising modules, improving performance, or migrating to a different API or idiom."},"review":{"examples":["Review this pull request","Audit this module for bugs before I merge it","Is this the right approach for the cache layer?"],"not_for":"Explaining how something works without judging it, which is `analysis`; applying the improvements, which is `refactor`. If the judgement asked for is specifically about attacks, credentials or data exposure, prefer `security`.","what":"Evaluate code, a diff or a design that already exists and report a judgement on it: correctness risks, quality, style, maintainability, or whether a change should be approved."},"security":{"examples":["Is this query vulnerable to SQL injection?","Stop leaking the API key into the logs and rotate it","Harden the file upload endpoint"],"not_for":"General quality review with no security angle, which is `review`; ordinary bug fixing, which is `code`.","what":"Work whose subject is security: vulnerabilities, authentication and authorisation, secrets and credentials, injection, cryptography, dependency advisories, hardening, or meeting a security requirement."},"test":{"examples":["Write tests for the configuration parser","Why is this test flaky in CI?","Raise coverage on the router module"],"not_for":"Fixing the production code that a failing test exposes as broken, which is `code`. Choose this only when the tests themselves are the deliverable.","what":"Work whose subject is automated tests: writing or fixing unit, integration or end-to-end tests, fixtures, mocks or coverage, or diagnosing a failing or flaky test suite."}},"instructions":{"background":"`project` describes the repository and its languages and `candidate_files` lists files a keyword search matched; both are background only. The developer may write in any language — judge the meaning the same way whatever the language.","focus":"Judge the goal of the request, not the vocabulary used to phrase it. A word such as \"test\", \"review\" or \"security\" appearing in passing does not by itself decide the category.","question":"Classify what the developer in `user_request` is asking the assistant to do, so that the right kind of model and the right context can be selected for the work.","tie_break":"If the request mixes several goals, pick the one that the bulk of the resulting work serves."},"type":"choice"}$json$::jsonb, 1),
  ('routing', 'is_destructive', $json${"criteria":{"false":"Carrying it out only reads, explains, analyses or produces new content that the developer may choose to apply later. Nothing already on disk or in a running system is changed as a direct result.","true":"Carrying it out overwrites or removes something that already exists: editing or deleting files, rewriting git history, dropping or migrating data, changing configuration or credentials, uninstalling dependencies, or running a command whose side effects are not trivially undone."},"instructions":{"guidance":"Judge the effect on things that exist now. Creating something entirely new alongside existing work is not destructive; replacing or removing existing work is.","question":"Would carrying out `user_request` modify, overwrite or delete code, data, configuration or infrastructure that already exists?"},"type":"noul"}$json$::jsonb, 2),
  ('routing', 'needs_repository_context', $json${"criteria":{"false":"The answer is identical for any project: a language, framework or tooling question, a definition, a generic how-to, a piece of throwaway code, or small talk. Nothing in this repository changes the correct answer.","true":"The answer depends on this repository's own code, configuration or history: editing or deleting an existing file, explaining what a named symbol in this project does, diagnosing a failure in this project, or writing new code that must match interfaces already defined here."},"instructions":{"context":"`project` names the repository and the languages it is written in. `candidate_files` lists files a keyword search already matched — they are hints that such files exist, not evidence that they are needed.","guidance":"Decide whether the correct answer depends on how this particular codebase is written, or whether it would be the same for any project.","question":"Does answering `user_request` correctly require reading the actual source files of this repository?"},"type":"noul"}$json$::jsonb, 3),
  ('routing', 'needs_tools', $json${"criteria":{"false":"A written answer fully satisfies the request: an explanation, a plan, a review, or a code snippet handed back to the developer to apply themselves.","true":"Satisfying the request means executing something or changing the filesystem: running tests, a build, a linter, a migration, a script or a shell command, applying an edit to a file on disk, or fetching live data from a service."},"instructions":{"guidance":"Acting means running commands or programs, executing a build or test suite, writing files to disk, querying a network service, or inspecting a running process. Judge what the request actually asks for, not what a thorough assistant might optionally do.","question":"Would fulfilling `user_request` require acting on the machine rather than only producing text?"},"type":"noul"}$json$::jsonb, 4),
  ('verification', 'addresses_request', $json${"criteria":{"false":{"examples":["solves a different problem or answers a question that was not asked","generic filler, an apology or a restatement with no substance","empty, cut off before it says anything, or just a transport or provider error message"],"when":"The reply is about something other than the request, or says nothing usable at all."},"true":{"also":"Directly refusing the request, or asking for one detail genuinely needed to proceed, still counts as addressing it.","when":"The reply delivers the kind of thing that was asked for — the explanation, the code, the review, the plan or the decision — even if it is partial or imperfect."}},"instructions":{"guidance":"Judge the fit between the request and the reply, not whether the reply is correct, grounded or thorough. The developer may write in any language — judge the meaning the same way whatever the language.","question":"Does `assistant_answer` respond to what `user_request` actually asked for?"},"type":"noul"}$json$::jsonb, 0),
  ('verification', 'unsupported_claims', $json${"criteria":{"false":{"also":"An answer that makes no factual claim about this repository belongs here too: general knowledge, restating the developer's own words, or code it openly offers as new rather than describing as already present.","not_a_defect":["saying that something is absent from the supplied context","declining to guess about code it was not shown"],"when":"Every statement about this repository can be traced to the blocks, allowing for paraphrase and summary."},"true":{"examples":["names a file, module, symbol or setting that appears in no block","states a signature, default value or return type that differs from the one shown","describes existing behaviour that the code shown contradicts","attributes to this project a dependency, convention or layout that no block shows"],"when":"At least one statement about this repository is stated as fact and the blocks neither show it nor imply it."}},"instructions":{"context":"`repository_context` holds the `FILE: <path>` blocks that were the assistant's only evidence about this repository while it answered `user_request`. Treat those blocks as the whole of the repository that was visible to it.","guidance":"Check each statement the answer makes about this repository — paths, modules, symbols, signatures, values, call sites, existing behaviour — against those blocks. Judge only whether the evidence is there; ignore style, length and whether the advice is good.","question":"Does `assistant_answer` present something about this repository as a fact that `repository_context` does not support?"},"type":"noul"}$json$::jsonb, 1),
  ('verification', 'verifiable_claims', $json${"criteria":{"false":{"examples":["a definition, or how a language, library or tool works in general","new code the reply proposes, presented as something to add rather than as something already here","a plan, an opinion, a question back to the developer, or small talk"],"when":"Nothing in the reply depends on this repository, so the blocks could neither confirm nor refute it."},"true":{"when":"The reply describes this particular codebase: it names a file, symbol, signature, setting or existing behaviour of this project, or asserts that something here does or does not exist."}},"instructions":{"guidance":"This asks only whether repository-specific claims are present, never whether they are right. A reply that needs no repository grounding is a normal, correct outcome, not a defect.","question":"Does `assistant_answer` make any statement about this repository whose truth could be confirmed or refuted by `repository_context`?"},"type":"noul"}$json$::jsonb, 2),
  ('asking', 'kind', $json${"criteria":{"multiple":"the question offers options and accepts as many as the developer wants","none":"there is no question to answer: the answer is information, or the question is rhetorical","noul":"the question is answered with yes or no","single":"the question offers options and expects exactly one"},"instructions":"Does the assistant's answer end by asking the developer something, so that the work depends on what they reply?","type":"choice"}$json$::jsonb, 0),
  ('asking', 'options_are_real', $json${"criteria":{"false":"something else: steps, examples, items of a report","true":"they are the question's alternatives"},"instructions":"Is the list in `options` exactly the set of alternatives that the question in `question` offers?","type":"noul"}$json$::jsonb, 1)
insert into public.jev_parameters (key, value) values
  ('block_margin', $json$0.2$json$::jsonb),
  ('noul_line', $json$0.5$json$::jsonb),
  ('scope_demand', $json$[0.35,0.55,0.7]$json$::jsonb),
  ('scope_levels', $json$["small change","feature","whole system"]$json$::jsonb),
  ('weights', $json${"bundles_requests":0.15,"goal_is_clear":0.4,"says_when_done":0.2,"says_where":0.25}$json$::jsonb)
